<?php
namespace Modules\Analytics\Controllers\Web;use Core\http\ResponseFactory;use Modules\Analytics\Services\AdminAccessCatalogService;use RuntimeException;
class AdminAccessCatalogController{public function __construct(private AdminAccessCatalogService$s){}public function index(){return$this->run(fn()=>['success'=>true,'data'=>$this->s->catalog()]);}public function saveRole(?int$id=null){return$this->run(fn()=>['success'=>true,'data'=>['id'=>$this->s->saveRole((int)auth()->id(),$id,$this->payload())]]);}public function savePermission(?int$id=null){return$this->run(fn()=>['success'=>true,'data'=>['id'=>$this->s->savePermission((int)auth()->id(),$id,$this->payload())]]);}public function deleteRole(int$id){return$this->run(function()use($id){$this->s->deleteRole((int)auth()->id(),$id);return['success'=>true];});}public function deletePermission(int$id){return$this->run(function()use($id){$this->s->deletePermission((int)auth()->id(),$id);return['success'=>true];});}private function payload():array{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$d=$raw===false?null:json_decode($raw,true);if(!is_array($d))throw new RuntimeException('داده معتبر نیست.');return$d;}private function run(callable$c){try{return ResponseFactory::json($c());}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}}
